begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000005','run@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000005','Run test');
insert into public.workspace_members values ('20000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000005','owner',now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select throws_ok($$select public.admit_analysis('20000000-0000-4000-8000-000000000005','{}',gen_random_uuid(),2,90000)$$,'23514',null,'malformed run input rejected at persistence boundary');
select throws_ok($$select public.admit_analysis('20000000-0000-4000-8000-000000000005','{"version":1,"template":"product_delivery","objective":"Release","context":"Team","hardConstraints":[],"conceptIds":[],"unknowns":"","workspaceId":"forged"}',gen_random_uuid(),2,90000)$$,'23514','Invalid analysis input','legacy conversion cannot hide malformed fields');
select throws_ok($$select public.admit_analysis('20000000-0000-4000-8000-000000000005',jsonb_build_object('version',2,'message',repeat('😀',2001),'history','[]'::jsonb),gen_random_uuid(),2,90000)$$,'23514','Invalid analysis input','direct v2 message uses the same UTF-16 limit as the app');
select throws_ok($$select public.admit_analysis('20000000-0000-4000-8000-000000000005',jsonb_build_object('version',2,'message','Question','history',jsonb_build_array(jsonb_build_object('role','user','text',repeat('😀',2001)))),gen_random_uuid(),2,90000)$$,'23514','Invalid analysis input','direct v2 history uses the same UTF-16 limit as the app');
select throws_ok($$select public.admit_analysis('20000000-0000-4000-8000-000000000005',jsonb_build_object('version',1,'template','product_delivery','objective',repeat('😀',2001),'context','Team','hardConstraints','[]'::jsonb,'conceptIds','[]'::jsonb,'unknowns',''),gen_random_uuid(),2,90000)$$,'23514','Invalid analysis input','legacy input cannot bypass the UTF-16 limit');
select is((select count(*) from public.analysis_runs where workspace_id='20000000-0000-4000-8000-000000000005'),0::bigint,'invalid request leaves no poisoned run');
select is(public.admit_analysis('20000000-0000-4000-8000-000000000005','{"template":"product_delivery","version":1,"objective":"Release","context":"Team","hardConstraints":[],"conceptIds":[],"unknowns":""}','50000000-0000-4000-8000-000000000001',2,90000)->>'kind','admitted','first run admitted');
select is((select request->>'message' from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000001'),'Release','legacy objective becomes the user message');
select is((select request->'history'->0->>'text' from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000001'),'The user message is the legacy objective. Concatenate these history messages to read the remaining user-confirmed request JSON: ' || ('{"template":"product_delivery","version":1,"context":"Team","hardConstraints":[],"conceptIds":[],"unknowns":""}'::jsonb)::text,'legacy snapshot keeps its other fields without repeating the objective');
select throws_ok($$select public.append_analysis_event((select id from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000001'),'{}')$$,'23514',null,'malformed events cannot poison run reads');
select is((select jsonb_array_length(events) from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000001'),0,'invalid event leaves existing state unchanged');
select is(public.admit_analysis('20000000-0000-4000-8000-000000000005','{"template":"product_delivery","version":1,"objective":"Release","context":"Team","hardConstraints":[],"conceptIds":[],"unknowns":""}','50000000-0000-4000-8000-000000000001',2,90000)->>'kind','duplicate','duplicate key rejected');
select is(public.admit_analysis('20000000-0000-4000-8000-000000000005','{"template":"product_delivery","version":1,"objective":"Release","context":"Team","hardConstraints":[],"conceptIds":[],"unknowns":""}','50000000-0000-4000-8000-000000000002',2,90000)->>'kind','admitted','second run admitted');
select is(public.admit_analysis('20000000-0000-4000-8000-000000000005','{"template":"product_delivery","version":1,"objective":"Release","context":"Team","hardConstraints":[],"conceptIds":[],"unknowns":""}','50000000-0000-4000-8000-000000000003',2,90000)->>'kind','quota','workspace concurrency enforced');
select public.finish_analysis((select id from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000001'),'cancelled',null,'[]','CANCELLED',null);
select is(public.admit_analysis('20000000-0000-4000-8000-000000000005','{"template":"product_delivery","version":1,"objective":"Release","context":"Team","hardConstraints":[],"conceptIds":[],"unknowns":""}','50000000-0000-4000-8000-000000000003',2,90000)->>'kind','admitted','cancelled run releases admission');
select throws_ok($$select public.admit_analysis('20000000-0000-4000-8000-000000000006','{"template":"product_delivery","version":1,"objective":"Release","context":"Team","hardConstraints":[],"conceptIds":[],"unknowns":""}',gen_random_uuid(),2,90000)$$,'42501',null,'forged workspace denied');
reset role;
update public.analysis_runs set deadline_at=now()-interval '1 second' where status='running' and workspace_id='20000000-0000-4000-8000-000000000005';
set local role authenticated;
select public.reconcile_analysis(id) from public.analysis_runs where status='running';
select is((select count(*) from public.analysis_runs where status='running'),0::bigint,'expired runs become timed out on read');
select throws_ok($$select public.admit_analysis('20000000-0000-4000-8000-000000000005',jsonb_build_object('version',2,'message','Question','history',jsonb_build_array(jsonb_build_object('role','assistant','text',repeat('a',20001)))),gen_random_uuid(),2,90000)$$,'23514','Invalid analysis input','an answer in history is capped at the answer limit');
select is(public.admit_analysis('20000000-0000-4000-8000-000000000005',jsonb_build_object('version',2,'message','Shorter please','history',jsonb_build_array(jsonb_build_object('role','user','text','Question'),jsonb_build_object('role','assistant','text',repeat('a',9000)))),'50000000-0000-4000-8000-000000000009',2,90000)->>'kind','admitted','an answer above 4000 characters does not block the next question');
select is((select count(*) from public.analysis_runs r cross join lateral jsonb_array_elements(r.request->'history') item where r.request_key='50000000-0000-4000-8000-000000000009' and item->>'role'='assistant' and length(item->>'text')=9000),1::bigint,'the long answer is stored whole');
select * from finish();
rollback;
